<?php

namespace App\Http\Controllers\Dr;

use App\Http\Controllers\Controller;
use Illuminate\Http\Request;
use App\Models\{User, Notes, Regions};

class DashboardController extends Controller
{
    public function index()
    {
        $user = auth()->user();
        $currentUser = auth()->user();

        if ($currentUser->type !== 'DR') {
            return response()->json(['message' => 'Only DR users can access this resource'], 403);
        }

        $services = $currentUser->service;
        if ($services->isEmpty()) {
            return response()->json(['message' => 'No services found for this user'], 404);
        }

        $serviceIds = $services->pluck('id');
        // DR sees all CSC users with non-taniere services
        $colleagues = $this->getColleagues();      
        $colleaguesCdc = $this->getColleaguesCDC();      
        $region = $this->getUserRegion($services);
        
        session(['user_region' => $region[0]['nom'] ?? null]);
        return view('dr.index', compact('colleagues','colleaguesCdc'));  
    }

    public function create($userId)
    {
        $labels = $this->getEvaluationLabelsCSC();
        $user = User::with('service')->findOrFail($userId);
        return view('dr.create', compact('labels','user'));
    }

    public function store(Request $request)
    {
        // Set username from session if empty
        $nom_utilisateur = $request->input('nom_utilisateur');
        $id_utilisateur = $request->input('id_utilisateur');
        $total_evaluation = $request->input('total_evaluation');

        // Prepare notes array
        $notes = [
            "Techniques de Management des Équipes" => $request->input('Techniques_de_Management_des_Équipes'),
            "Techniques de Commercialisation" => $request->input('Techniques_de_Commercialisation'),
            "Techniques de Conduite du Changement" => $request->input('Techniques_de_Conduite_du_Changement'),
            "Capacité d'impliquer les équipes" => $request->input("Capacité_d'impliquer_les_équipes"),
            "Gestion des budgets" => $request->input('Gestion_des_budgets'),
            "Techniques d'Analyse du Marché" => $request->input("Techniques_d'Analyse_du_Marché"),
            "Techniques Statistiques" => $request->input('Techniques_Statistiques'),
            "Techniques de Communication" => $request->input('Techniques_de_Communication'),
            "Connaissance produit" => $request->input('Connaissance_produit'),
            "Techniques de Veille Concurrentielle" => $request->input('Techniques_de_Veille_Concurrentielle'),
            "Analyse des Données et Reporting" => $request->input('Analyse_des_Données_et_Reporting'),
            "Présentation" => $request->input('Présentation'),
            "Planification" => $request->input('Planification'),
            "Méthode" => $request->input('Méthode'),
            "Gestion du temps" => $request->input('Gestion_du_temps'),
            "Gestion des priorités" => $request->input('Gestion_des_priorités'),
            "Organisation des informations" => $request->input('Organisation_des_informations'),
            "Capacité à influencer" => $request->input('Capacité_à_influencer'),
            "Force de conviction" => $request->input('Force_de_conviction'),
            "Suivi et analyse des ventes" => $request->input('Suivi_et_analyse_des_ventes'),
            "Courage managérial" => $request->input('Courage_managérial'),
            "Leaderships" => $request->input('Leaderships'),
            "Leadership inspirationnel" => $request->input('Leadership_inspirationnel'),
            "Partage des connaissances et compétences" => $request->input('Partage_des_connaissances_et_compétences'),
            "Respect et écoute des opinions des autres" => $request->input('Respect_et_écoute_des_opinions_des_autres'),
            "Capacité de mobilisation des équipes" => $request->input('Capacité_de_mobilisation_des_équipes')
        ];
        // dd($notes);
        // Create the note
        Notes::create([
            'id_utilisateur' => $id_utilisateur, // You might want to use auth()->id() here
            'nom_utilisateur' => $nom_utilisateur,
            'notes' => json_encode($notes),
            'total' => $total_evaluation,
            'creator_id' => auth()->user()->matricule
        ]);
        return redirect('dr');
    }

    public function show($userId)
    {
        $user = User::with('service')->findOrFail($userId);
        $evaluations = Notes::with(['user', 'creator'])
            ->where('id_utilisateur', $userId)
            ->get();
        $services = $user->service;
        $regions = $this->getUserRegion($services);
        $region = $regions[0]['nom']; 
        return view('dr.show', compact('user','region' ,'evaluations'));
    }

    public function detail($noteId)
    {
        $evaluation = Notes::with(['user', 'creator'])
            ->where('id_note', $noteId)
            ->firstOrFail();
        
        return view('dr.note', [
            'evaluation' => $evaluation,
            'labels' => $this->getEvaluationLabelsCSC(),
        ]);
    }

    protected function getEvaluationLabelsCSC(): array
    {
        return [
            "Techniques de Management des Équipes" => [ '5',["Manque de communication avec l'équipe. Ne définit pas clairement les objectifs. Ne fournit pas de feedback ni de soutien adéquats. Réagit de manière autoritaire aux problèmes.","Commence à communiquer les objectifs et les attentes, mais peut manquer de clarté. Fournit sporadiquement des feedbacks et un soutien limité. Utilise un style de gestion directif.","Communique efficacement les objectifs et les attentes. Fournit un feedback constructif et un soutien approprié aux membres de l'équipe. Encourage la collaboration et la prise d'initiative.","Gère activement les performances de l'équipe. Fournit un feedback continu pour favoriser le développement des membres. Encourage l'autonomie et la responsabilisation. Utilise des techniques de motivation efficaces.","Expert en techniques de management des équipes. Crée un environnement de travail inspirant. Développe les compétences de leadership au sein de l'équipe. Sait gérer les conflits, favoriser l'innovation et atteindre des résultats exceptionnels."], '4'],
            "Techniques de Commercialisation" => [ '3',["Manque de compréhension des besoins du marché. Utilise des approches de vente agressives. Ne personnalise pas les stratégies de vente. Ne sait pas présenter efficacement les produits.","Commence à comprendre les besoins du marché. Utilise des techniques de vente de base. Personnalise parfois les stratégies de vente en fonction du client. Présente les produits de manière rudimentaire.","Comprend bien les besoins du marché et les préférences des clients. Utilise des stratégies de vente adaptées. Personnalise les approches en fonction des différents segments de clientèle. Présente les produits de manière claire et convaincante.","Maîtrise les techniques avancées de commercialisation. Anticipe les tendances du marché. Utilise des stratégies de vente personnalisées et innovantes. Présente les produits de manière percutante et différenciée.","Expert en techniques de commercialisation. Identifie de nouvelles opportunités de marché. Développe des stratégies de vente novatrices et efficaces. Sait anticiper et répondre aux besoins changeants des clients de manière proactive."], '4'],
            "Techniques de Conduite du Changement" => [ '5',["Résistance au changement. Manque de communication. Absence de planification du changement. Ignorance des réactions des parties prenantes. Manque de suivi.","Reconnaît la nécessité du changement mais éprouve des difficultés à le communiquer. Élabore des plans de changement de base. Implique les parties prenantes de manière limitée. Suit partiellement l'avancement du changement.","Communique efficacement les raisons du changement et les bénéfices attendus. Établit des plans de changement détaillés. Implique activement les parties prenantes et gère les résistances. Assure un suivi régulier de l'avancement du changement.","Gère le changement de manière proactive. Communique de manière transparente et empathique. Élabore des plans de changement stratégiques. Implique pleinement les parties prenantes à tous les niveaux. Surveille de près l'impact du changement et ajuste les stratégies en conséquence.","Expert en techniques de conduite du changement. Inspire et motive les équipes à embrasser le changement. Anticipe les réactions des parties prenantes et adapte les stratégies en conséquence. Crée une culture d'adaptabilité et d'innovation au sein de l'organisation"], '4'],
            "Capacité d'impliquer les équipes" => [ '4',["Implique rarement les membres de l'équipe dans les prises de décision. Ne sollicite pas leur retour d'expérience. Donne des directives sans expliquer le contexte.","Implique occasionnellement les membres de l'équipe dans les prises de décision. Écoute leurs idées mais ne les intègre pas systématiquement. Communique les objectifs sans fournir de contexte approfondi.","Implique activement les membres de l'équipe dans les prises de décision. Sollicite leur retour d'expérience et intègre leurs idées. Communique clairement les objectifs et explique le contexte des tâches à accomplir.","Implique systématiquement les membres de l'équipe dans les prises de décision. Favorise la collaboration et la co-création. Encourage la diversité des points de vue et la prise de risque calculée. Communique de manière transparente et motive l'engagement.","Expert en capacité d'impliquer les équipes. Implique de manière innovante et inspirante les membres de l'équipe. Favorise un climat de confiance et d'ouverture. Encourage la créativité et l'autonomie. Les membres de l'équipe sont pleinement investis et engagés dans la réussite commune."], '4'],
            "Gestion des budgets" => [ '2',["A tendance à dépasser régulièrement les budgets alloués. Manque de suivi des dépenses. Ne tient pas compte des prévisions budgétaires.","A tendance à dépasser régulièrement les budgets alloués. Manque de suivi des dépenses. Ne tient pas compte des prévisions budgétaires.","Parfois dépasse les budgets alloués. Suit un suivi des dépenses de manière irrégulière. Commence à utiliser des outils de suivi budgétaire de base. Respecte généralement les prévisions budgétaires.","Respecte les budgets alloués dans la plupart des cas. Effectue un suivi régulier des dépenses. Utilise des outils de suivi budgétaire pour évaluer la performance financière. Ajuste les prévisions budgétaires en cas de dépassement.","Gère efficacement les budgets alloués. Suit de près les dépenses et les recettes. Utilise des outils avancés pour l'analyse financière. Anticipe les besoins budgétaires futurs et propose des ajustements pertinents.","Expert en gestion des budgets. Gère les budgets de manière stratégique et proactive. Utilise des techniques avancées pour optimiser les ressources financières. Anticipe les risques financiers et met en place des mesures d'atténuation. Est reconnu pour son excellence en matière de gestion financière."], '4'],
            "Techniques d'Analyse du Marché" => [ '4',["Manque de compréhension des méthodes d'analyse du marché. Ne sait pas interpréter les données de marché. Utilise des sources d'information non fiables. Formule des conclusions erronées.","Comprend les bases de l'analyse du marché. Utilise des outils d'analyse simples. Interprète les données de manière basique. Utilise des sources d'information générales. Formule des conclusions basées sur des hypothèses limitées.","Maîtrise les principes d'analyse du marché. Utilise une variété d'outils d'analyse pour recueillir et interpréter les données. Identifie des tendances et des insights pertinents. Utilise des sources d'information fiables. Formule des conclusions fondées sur des preuves solides.","Utilise des méthodes avancées d'analyse du marché. Intègre des données qualitatives et quantitatives pour obtenir des insights approfondis. Identifie des opportunités et des menaces de manière proactive. Formule des recommandations stratégiques basées sur une analyse approfondie.","Expert en techniques d'analyse du marché. Anticipe les évolutions du marché. Utilise des analyses prédictives pour prendre des décisions éclairées. Identifie des niches de marché et des segments de clients lucratifs. Influence les stratégies commerciales globales de l'entreprise."], '4'],
            "Techniques Statistiques" => [ '2',["Manque de compréhension des concepts statistiques de base. Incapacité à interpréter les données. Utilisation inadéquate des outils statistiques. Erreurs fréquentes dans les calculs.","Comprend les concepts statistiques fondamentaux. Utilise des outils statistiques simples. Capable de résumer des données de base. Fait des erreurs occasionnelles dans l'analyse.","Maîtrise les concepts statistiques avancés. Utilise une variété d'outils statistiques pour analyser les données. Interprète correctement les résultats. Capable de tirer des conclusions significatives à partir des données. Minimise les erreurs dans les calculs.","Utilise des techniques statistiques avancées pour analyser des ensembles de données complexes. Identifie des modèles et des tendances significatifs. Effectue des analyses statistiques approfondies avec précision. Formule des recommandations basées sur des analyses rigoureuses.","Expert en techniques statistiques. Applique des méthodes statistiques sophistiquées pour résoudre des problèmes complexes. Possède une compréhension approfondie des concepts statistiques avancés. Contribue de manière significative à la prise de décision stratégique en fournissant des analyses statistiques de pointe."], '3'],
            "Techniques de Communication" => [ '2',["Communication inefficace. Manque de clarté et de cohérence. Ne tient pas compte du public cible. Utilise un langage inapproprié. Ne sait pas écouter activement.","Commence à améliorer la clarté de la communication. Adapte son discours au public cible. Utilise un langage plus adapté. Commence à écouter activement les autres.","Communique clairement et de manière cohérente. Adapte son message au public visé. Utilise un langage approprié. Pratique l'écoute active en posant des questions pertinentes et en montrant de l'empathie.","Communique de manière impactante et persuasive. S'adapte facilement à différents publics. Utilise un langage précis et engageant. Démontre une écoute active en reformulant et en posant des questions pertinentes.","Expert en techniques de communication. Communique de manière influente et inspirante. Capable de captiver et d'engager n'importe quel public. Utilise un langage puissant et persuasif. Maîtrise parfaitement l'écoute active et la communication non verbale."], '4'],
            "Connaissance produit" => [ '2',["Montre une connaissance limitée des produits. Ne peut pas répondre aux questions de base des clients.","A une compréhension de base des produits mais manque de détails. Peut répondre à des questions simples des clients.","Possède une connaissance approfondie des produit (argumenataires produit). Peut expliquer les caractéristiques, les avantages et les cas d'utilisation du produit de manière détaillée.","Maîtrise tous les aspects des produits. Peut résoudre des problèmes complexes et anticiper les besoins des clients en fonction des fonctionnalités du produit.","Expert en connaissance produit. Est capable de former d'autres membres de l'équipe sur les détails techniques des produits. Peut proposer des améliorations et des innovations basées sur une compréhension approfondie du marché et des besoins des clients."], '3'],
            "Techniques de Veille Concurrentielle" => [ '3',["Manque de compréhension des principes de base de la veille concurrentielle. Utilisation de sources d'informations limitées. Analyse superficielle des concurrents. Peu de réactivité aux changements du marché.","Commence à comprendre les principes de la veille concurrentielle. Utilise une variété de sources d'informations. Analyse les concurrents de façon élémentaire. Réagit aux changements du marché de manière limitée.","Maîtrise les concepts de base de la veille concurrentielle. Utilise des outils et des sources diversifiés pour collecter des informations sur les concurrents. Analyse les forces et les faiblesses des concurrents de manière approfondie. Réagit de manière proactive aux évolutions du marché.","Utilise des techniques avancées de veille concurrentielle pour obtenir des informations stratégiques sur les concurrents. Analyse en profondeur les stratégies des concurrents et anticipe leurs mouvements. Réagit rapidement et efficacement aux changements du marché. Formule des recommandations stratégiques basées sur une analyse approfondie.","Expert en techniques de veille concurrentielle. Anticipe les actions des concurrents et identifie les opportunités émergentes. Utilise des analyses prédictives pour évaluer les performances des concurrents. Influence les décisions stratégiques de l'entreprise en fournissant des informations clés sur le marché."], '4'],
            "Analyse des Données et Reporting" => [ '3',["Compréhension limitée des concepts d'analyse des données. Utilisation inadéquate des outils d'analyse. Présentation de rapports peu claire et non structurée. Manque de précision dans les analyses.","Comprend les concepts de base de l'analyse des données. Utilise des outils d'analyse simples. Présente des rapports avec une certaine structure. Fait des analyses de base mais avec des lacunes.","Maîtrise les techniques d'analyse des données. Utilise une variété d'outils pour extraire des insights. Présente des rapports clairs et informatifs. Effectue des analyses approfondies pour identifier des tendances et des corrélations significatives.","Utilise des méthodes avancées d'analyse des données pour obtenir des insights approfondis. Crée des tableaux de bord interactifs pour visualiser les données. Présente des rapports détaillés avec des recommandations basées sur des analyses approfondies.","Expert en analyse des données et reporting. Utilise des techniques d'analyse prédictive pour anticiper les tendances futures. Crée des modèles de prévision sophistiqués. Produit des rapports perspicaces qui influencent les décisions stratégiques de l'entreprise."], '4'],
            "Présentation" => [ '3',["Présentation peu structurée et confuse. Manque de clarté dans les idées exprimées. Utilisation inadaptée des supports visuels. Communication inefficace avec le public.","Commence à structurer les présentations de manière plus cohérente. Communique les idées de base de manière compréhensible. Utilise des supports visuels de manière basique. Engage de façon limitée avec le public.","Présentation claire et structurée. Communique efficacement les informations clés. Utilise des supports visuels appropriés pour renforcer le message. Engage le public de manière adéquate. Répond aux questions avec précision.","Présentation fluide et captivante. Communique de manière persuasive et impactante. Utilise des supports visuels créatifs pour illustrer les points clés. Interagit de manière dynamique avec le public. Gère efficacement les questions et les commentaires.","Expert en présentation. Capable de captiver et d'inspirer n'importe quel public. Communique de façon convaincante et mémorable. Utilise des supports visuels innovants pour renforcer le message. Interagit avec assurance et empathie. Répond de manière experte aux questions et aux défis."], '3'],
            "Planification" => [ '3',["Difficulté à établir des objectifs clairs et mesurables. Manque de structuration dans l'organisation des tâches. Ne tient pas compte des contraintes temporelles. Réagit au fur et à mesure sans anticipation.","Commence à définir des objectifs spécifiques mais non toujours mesurables. Organise les tâches de manière basique. Commence à respecter certaines échéances. Commence à anticiper certains obstacles.","Établit des objectifs clairs, mesurables et atteignables. Organise efficacement les tâches en séquences logiques. Respecte les échéances fixées. Anticipe les obstacles potentiels et élabore des plans d'action.","Planifie de manière proactive en tenant compte des contraintes temporelles et des ressources disponibles. Élabore des plans détaillés et flexibles pour s'adapter aux changements. Respecte rigoureusement les délais. Identifie et gère les risques.","Expert en planification. Élabore des stratégies globales complexes et détaillées. Anticipe les évolutions du marché et des besoins. Dirige des projets de grande envergure en utilisant des approches innovantes. Forme et guide les autres dans l'élaboration de plans stratégiques."], '3'],
            "Méthode" => [ '4',["Difficulté à suivre un processus structuré pour résoudre des problèmes. Manque de rigueur dans l'approche des tâches. Préfère l'approche intuitive à la méthode. Difficulté à analyser les problèmes de manière systématique.","Commence à suivre des méthodes établies pour aborder les problèmes. Développe une approche plus structurée pour les tâches. Commence à analyser les problèmes de manière plus systématique. Fait preuve de plus de rigueur dans l'exécution des tâches","Utilise des méthodes établies pour résoudre les problèmes de manière efficace. Suit un processus méthodique pour aborder les tâches complexes. Analyse les problèmes de manière approfondie et propose des solutions pertinentes. Applique des techniques éprouvées pour optimiser les processus.","Utilise des approches méthodiques avancées pour résoudre des problèmes complexes. Développe et adapte des méthodes pour répondre à des défis spécifiques. Analyse les problèmes de manière approfondie et créative. Identifie des opportunités d'amélioration continue.","Expert en méthodologie. Maîtrise une variété de méthodes et d'approches pour aborder des problèmes complexes. Développe de nouvelles méthodes et outils pour résoudre des défis uniques. Analyse de manière critique les processus existants et propose des solutions novatrices. Partage son expertise en méthodologie et forme les autres."], '3'],
            "Gestion du temps" => [ '5',["Difficulté à respecter les délais. Procrastination fréquente. Manque de priorisation des tâches. Difficulté à estimer le temps nécessaire pour accomplir les tâches.","Commence à respecter certains délais. Travaille sur la procrastination. Commence à prioriser les tâches en fonction de leur importance. Estime plus précisément le temps nécessaire pour accomplir les tâches. Utilise des outils simples de gestion du temps.","Respecte généralement les délais impartis. Priorise efficacement les tâches en fonction des objectifs. Estime avec précision le temps nécessaire pour chaque tâche. Utilise des outils de gestion du temps pour planifier ses activités quotidiennes. Réajuste son emploi du temps en cas d'imprévus." ,"Gère efficacement son temps en respectant strictement les échéances. Priorise les tâches de manière stratégique pour atteindre les objectifs fixés. Estime de manière précise le temps nécessaire pour chaque activité. Utilise des techniques avancées de gestion du temps pour optimiser sa productivité. Anticipe les urgences et s'adapte rapidement aux changements.","Expert en gestion du temps. Maîtrise la planification à long terme et la gestion des priorités. Respecte les délais les plus serrés. Estime avec précision le temps nécessaire pour chaque tâche. Utilise des méthodes avancées de gestion du temps pour maximiser son efficacité. Partage ses compétences en gestion du temps et forme les autres à améliorer leur efficacité."], '4'],
            "Gestion des priorités" => [ '5',["Difficulté à identifier les tâches importantes. Se laisse souvent distraire par des tâches secondaires. Manque de vision globale sur les objectifs à long terme. Tendance à se concentrer sur les tâches faciles plutôt que sur les plus importantes.","Commence à distinguer les tâches importantes des tâches secondaires. Travaille sur la minimisation des distractions. Commence à établir des objectifs à court terme. Commence à hiérarchiser les tâches en fonction de leur importance.","Identifie efficacement les tâches prioritaires. Établit des objectifs clairs à court et moyen terme. Hiérarchise les tâches en fonction de leur impact sur les objectifs. Gère les urgences de manière adéquate tout en restant concentré sur les priorités principales.","Priorise de manière proactive les tâches en fonction des objectifs organisationnels. Établit des objectifs à court, moyen et long terme alignés sur la vision globale de l'entreprise. Réagit de manière efficace aux changements de priorités tout en maintenant le cap sur les objectifs principaux.","Expert en gestion des priorités. Anticipe les besoins futurs et ajuste les priorités en conséquence. Élabore des stratégies complexes pour gérer des projets multidimensionnels. Coordonne efficacement les activités de différentes équipes en alignant les priorités. Partage son expertise en gestion des priorités et forme les autres pour améliorer leur capacité à gérer efficacement leurs tâches."], '4'],
            "Organisation des informations" => [ '5',["Difficulté à structurer les données de manière cohérente. Manque de méthodes pour classer et retrouver les informations. Utilisation incohérente des outils de stockage d'informations. Perte fréquente de données importantes.","Commence à organiser les données avec une certaine cohérence. Utilise des méthodes simples pour classer et retrouver les informations. Commence à adopter des outils de stockage d'informations plus efficaces. Égare occasionnellement des données importantes.","Structure les données de manière logique et cohérente. Utilise des méthodes de classification efficaces pour organiser les informations. Maîtrise les outils de stockage d'informations pour accéder rapidement aux données pertinentes. Récupère facilement des informations essentielles en cas de besoin.","Organise les données de manière avancée en utilisant des systèmes de classification complexes. Exploite pleinement les fonctionnalités des outils de gestion de l'information. Accède rapidement aux informations pertinentes et les partage efficacement avec les autres. Évite les doublons et maintient des bases de données propres et actualisées.","Expert en organisation des informations. Conçoit des structures de données sophistiquées pour gérer des volumes importants d'informations. Développe des solutions personnalisées pour l'organisation et la récupération des données. Partage son savoir-faire en matière d'organisation des informations et forme les autres pour optimiser leur gestion de l'information."], '3'],
            "Capacité à influencer" => [ '5',["Difficulté à communiquer efficacement ses idées. Manque de confiance en soi. Peu convaincant dans ses arguments. Résistance aux feedbacks et aux idées des autres.","Commence à s'exprimer de manière plus claire et convaincante. Travaille sur le renforcement de sa confiance en soi. Écoute activement les autres. Commence à adapter son discours en fonction de son public.","Communique avec clarté et persuasivité. Sait influencer les autres en utilisant des arguments solides. Écoute activement et prend en compte les points de vue des autres. Sait s'adapter à différents interlocuteurs. Utilise des techniques de persuasion efficaces.","Influence efficacement les autres en utilisant des arguments percutants et une communication persuasive. Sait gérer les objections et les résistances de manière constructive. Établit des relations de confiance et de collaboration. Sait adapter son approche en fonction des personnalités et des contextes. Utilise des tactiques avancées de persuasion.","Expert en capacité à influencer. Maîtrise l'art de la communication persuasive dans des situations complexes. Influence positivement les décisions et les actions des autres. Sait gérer les conflits et les résistances avec habileté. Développe des alliances stratégiques pour atteindre des objectifs communs. Partage son expertise en influence et forme les autres à devenir des leaders influents."], '4'],
            "Force de conviction" => [ '4',["Manque de confiance en soi dans ses arguments. Difficulté à exprimer clairement ses opinions. Peu persuasif dans ses communications. Réticence à défendre ses idées face à l'opposition.","Commence à exprimer ses opinions de manière plus assurée. Travaille sur le renforcement de sa confiance en soi. Défend ses idées de manière plus convaincante. Commence à utiliser des arguments solides pour étayer ses points de vue.","Exprime ses opinions avec assurance et clarté. Utilise des arguments logiques et pertinents pour défendre ses idées. Persuade les autres en utilisant des exemples concrets et des données probantes. Sait gérer les objections de manière constructive.","Convainc avec aisance en utilisant des arguments percutants et une communication persuasive. Maîtrise l'art de la rhétorique pour captiver son auditoire. Sait influencer les décisions en présentant des arguments convaincants. Gère les désaccords de manière constructive.","Expert en force de conviction. Maîtrise l'art de la persuasion dans des situations complexes. Influence positivement les opinions et les actions des autres. Sait adapter son discours en fonction de son public. Développe des arguments solides et percutants pour défendre ses idées. Partage son expertise en force de conviction et forme les autres à devenir des communicateurs persuasifs."], '4'],
            "Suivi et analyse des ventes" => [ '5',["Difficulté à suivre les données de vente de manière systématique. Manque de compréhension des outils d'analyse des ventes. Ne parvient pas à identifier les tendances clés.","Commence à enregistrer et à suivre les données de vente de manière plus régulière. Se familiarise avec les outils d'analyse des ventes de base. Commence à repérer quelques tendances pertinentes.","Suit et analyse les données de vente de manière régulière. Utilise efficacement les outils d'analyse des ventes pour identifier les tendances et les opportunités. Sait interpréter les données pour prendre des décisions éclairées.","Analyse de manière approfondie les données de vente pour identifier des tendances significatives. Utilise des outils avancés pour prévoir les performances futures. Identifie des opportunités d'amélioration des ventes et propose des stratégies pertinentes.","Expert en suivi et analyse des ventes. Maîtrise les techniques d'analyse prédictive pour anticiper les tendances du marché. Identifie des pistes d'optimisation des processus de vente. Partage son expertise en suivi et analyse des ventes pour améliorer les performances de l'équipe."], '4'],
            "Courage managérial" =>[ '5',["Évite les prises de décision difficiles. Manque de fermeté dans la gestion des conflits. Réticent à prendre des risques calculés. Craint les réactions négatives de l'équipe.","Commence à prendre des décisions courageuses malgré les défis. S'affirme davantage dans la gestion des conflits. Ose prendre des risques mesurés pour atteindre les objectifs. Accepte les critiques constructives et les utilise pour progresser.","Prend des décisions difficiles avec résolution. Gère efficacement les conflits en faisant preuve de fermeté et de compassion. Assume les risques calculés pour innover et améliorer les performances. Encourage l'équipe à sortir de sa zone de confort.","Prend des décisions courageuses et réfléchies, même en situation d'incertitude. Gère les conflits avec tact et diplomatie, en maintenant un environnement de travail positif. Prend des risques calculés pour stimuler la croissance et l'innovation. Inspire l'équipe par son exemple et sa détermination.","Expert en courage managérial. Prend des décisions audacieuses et stratégiques pour le bien de l'organisation. Gère les conflits complexes avec assurance et empathie. Assume des risques calculés pour mener l'entreprise vers de nouveaux sommets. Crée une culture d'entreprise basée sur la confiance, l'innovation et la croissance."], '3'],
            "Leaderships" => [ '5',["Manque de vision claire pour l'équipe. Évite les responsabilités de leadership. Ne communique pas efficacement les objectifs et les attentes. N'hésite à prendre des décisions stratégiques.","ommence à développer une vision pour l'équipe. Assume progressivement des responsabilités de leadership. Communique de manière plus claire les objectifs et les attentes. Prend des décisions stratégiques avec l'aide de l'équipe.","Articule une vision inspirante pour l'équipe. Assume efficacement les responsabilités de leadership. Communique de manière efficace les objectifs et les attentes. Prend des décisions stratégiques en consultant l'équipe. Encourage la collaboration et la participation des membres de l'équipe.","Inspire l'équipe à travers une vision convaincante et motivante. Dirige efficacement en fixant des objectifs clairs et en fournissant des feedbacks constructifs. Prend des décisions stratégiques en évaluant les différentes perspectives. Développe les compétences de leadership au sein de l'équipe. Favorise un climat de confiance et d'innovation.","Expert en leadership. Incarne les valeurs et la vision de l'organisation. Dirige avec intégrité et empathie. Inspire et motive les autres à atteindre l'excellence. Prend des décisions stratégiques et audacieuses pour assurer la croissance et le succès à long terme. Développe une culture d'entreprise basée sur l'innovation, la collaboration et l'excellence."], '4'],
            "Leadership inspirationnel" => [ '5',["Manque de vision inspirante et motivationnelle. Ne communique pas efficacement la vision aux membres de l'équipe. N'inspire pas les autres à atteindre leur plein potentiel. Résiste au changement et à l'innovation.","Commence à développer une vision inspirante pour l'équipe. Communique la vision de manière plus claire et engageante. Encourage les membres de l'équipe à s'épanouir et à relever des défis. Montre de l'ouverture au changement et à l'innovation.","Articule une vision inspirante et motivante pour l'équipe. Communique efficacement la vision et les objectifs. Inspire les autres à donner le meilleur d'eux-mêmes. Encourage la créativité et l'innovation au sein de l'équipe. Favorise un climat de confiance et d'engagement.","Incarne la vision de manière authentique et passionnée. Communique la vision de manière inspirante et persuasive. Inspire et motive les membres de l'équipe à exceller et à se dépasser. Encourage l'innovation et soutient les initiatives créatives. Crée un environnement propice à la croissance personnelle et professionnelle.","Expert en leadership inspirationnel. Incarne les valeurs et la vision de l'organisation de manière exceptionnelle. Inspire un engagement passionné et un dévouement total des membres de l'équipe. Crée une culture d'entreprise basée sur la passion, l'innovation et l'excellence. Guide et forme les futurs leaders pour qu'ils deviennent à leur tour des inspirations pour les autres."], '4'],
            "Partage des connaissances et compétences" => [ '3',["Garde les informations pour soi. Réticent à aider les autres. Ne participe pas activement aux sessions de partage de connaissances. Ne fournit pas de feedback constructif.","Partage occasionnellement des informations, mais de manière limitée. Commence à aider les autres, mais de façon irrégulière. Participe aux sessions de partage de connaissances de manière passive. Fournit parfois un feedback de bas","Partage régulièrement des connaissances et compétences avec les autres. Aide activement les collègues à résoudre des problèmes et à développer leurs compétences. Contribue de manière constructive lors des sessions de partage de connaissances. Fournit un feedback utile et constructif pour favoriser la croissance des autres.","Partage de manière proactive ses connaissances et compétences avec les autres. Mentor(e) les membres de l'équipe pour les aider à progresser dans leur développement professionnel. Anime des sessions de partage de connaissances et encourage la participation de tous. Fournit un feedback approfondi et personnalisé pour soutenir le développement des autres.","Expert en partage des connaissances et compétences. Crée un environnement propice à l'apprentissage et à l'échange de savoir. Partage de manière stratégique des connaissances pour stimuler l'innovation et la croissance. Mentor(e) et forme activement les futurs leaders de l'organisation. Anime des ateliers et des formations pour renforcer les compétences de l'équipe."], '3'],
            "Respect et écoute des opinions des autres" => [ '3',["Manque de respect pour les opinions des autres, tendance à imposer ses propres idées sans considération pour les autres.","Commence à développer des compétences en respect et écoute des opinions. Par exemple, peut commencer à prendre en compte les opinions des autres lors des réunions, mais continue parfois à interrompre ou à imposer ses propres idées.","Respecte les opinions des autres, écoute activement et valorise la diversité des idées. Par exemple, encourage les membres de l'équipe à exprimer leurs pensées lors des discussions et montre une ouverture à considérer différents points de vue.","Excellente capacité à écouter avec empathie, à respecter les opinions différentes et à favoriser un climat de confiance et de respect mutuel. Par exemple, prend le temps d'écouter attentivement lors des réunions, encourage les échanges constructifs et traite les opinions divergentes avec respect.","Expert en respect et écoute des opinions, crée un environnement inclusif, encourage la diversité de pensée et prend des décisions en considérant différents points de vue. Par exemple, favorise un espace où chacun se sent écouté et valorisé, et intègre activement les perspectives variées dans les prises de décision."], '3'],             
            "Capacité de mobilisation des équipes" =>[ '5',["Ne parvient pas à motiver ou inspirer les membres de l'équipe. Manque de communication et de coordination. Les membres de l'équipe sont désengagés.","Tente de motiver les membres de l'équipe, mais de manière inégale. Communique de manière sporadique ou peu claire. Les membres de l'équipe montrent un certain niveau d'engagement.","Motive efficacement les membres de l'équipe. Communique de manière claire et transparente. Encourage la collaboration et la participation active. Les membres de l'équipe sont engagés et impliqués dans les tâches.","Inspire et motive constamment les membres de l'équipe. Communique de manière persuasive et inspirante. Favorise un climat de confiance et d'ouverture. Les membres de l'équipe travaillent ensemble de manière harmonieuse et efficace.","Expert en capacité de mobilisation des équipes. Inspire un engagement exceptionnel chez les membres de l'équipe. Communique de manière charismatique et motivante. Encourage l'innovation et la créativité. Les membres de l'équipe sont passionnés et dévoués à atteindre les objectifs communs."], '4'],
        ];
    }

    protected function getColleagues(){
        $currentUser = auth()->user();
        $currentUserRegion = $currentUser->service->first()->region ?? null;

        // dd($currentUserRegion);/

        $cscUsers = User::where('type', 'CSC')
            ->with(['service' => function($query) use ($currentUserRegion) {
                $query->where('taniere', '0')
                    ->when($currentUserRegion, function($q) use ($currentUserRegion) {
                        $q->where('region', $currentUserRegion);
                    });
            }, 'notes'])
            ->whereHas('service', function($query) use ($currentUserRegion) {
                $query->where('taniere', '0')
                    ->when($currentUserRegion, function($q) use ($currentUserRegion) {
                        $q->where('region', $currentUserRegion);
                    });
            })
            ->get()
            ->map(function ($user) {
                $user->evaluation_count = $user->notes()->count();
                $user->latest_evaluation = $user->notes->first();
                $user->has_score = $user->notes->isNotEmpty();
                unset($user->notes);
                return $user;
            });
        
        return $cscUsers;
    }

    protected function getColleaguesCDC()
    {
        $user = auth()->user();
        return User::where('parent_id',$user->matricule)
            ->Where(function ($query) {
                $query->whereHas('service', fn($q) => $q->where('type', 'CDC TT'));
            })
            ->with(['service', 'notes' => fn($q) => $q->latest()->limit(1)])
            ->get()
            ->map(function ($user) {
                $user->evaluation_count = $user->notes()->count();
                $user->latest_evaluation = $user->notes->first();
                $user->has_score = $user->notes->isNotEmpty();
                unset($user->notes);
                return $user;
            });
    }

    protected function getUserRegion($services)
    {
        $regions = Regions::find($services->pluck('region'));
        return json_decode($regions, true);
    }

}
